# Linux wording (Lx.Words): the same sentences, honest about how the sign-in is kept there
KR = " (and encrypted, when your desktop has a keyring)"
KRH = " (ומוצפנת, כשיש בשולחן העבודה מחזיק מפתחות)"
LXW = [("Elixar keeps it encrypted on this PC in a folder only administrators can open", "Elixar keeps it on this PC in a folder only your account can open" + KR,
        "שומר אותה מוצפנת במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח", "שומר אותה במחשב הזה בתיקייה שרק החשבון שלך יכול לפתוח" + KRH),
       ("is encrypted on this PC in a folder only administrators can open", "is kept on this PC in a folder only your account can open" + KR,
        "במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח", "במחשב הזה בתיקייה שרק החשבון שלך יכול לפתוח" + KRH)]
for k, v in list(HE.items()):
    nk, nv = k, v
    for e1, e2, h1, h2 in LXW:
        if e1 in nk: nk = nk.replace(e1, e2); nv = nv.replace(h1, h2).replace("מוצפנת במחשב", "נשמרת במחשב").replace("מוצפן במחשב", "נשמר במחשב")
    if nk != k and nk not in HE: HE[nk] = nv
HE.setdefault("Alerts: the system disk is almost full (your limit in Automation, or 15%)", "התראות: דיסק המערכת כמעט מלא (הגבול שלך באוטומציה, או 15%)")
HE.setdefault("Follow the system", "לפי המערכת")
